+int main(void)
+{
+    if (!mkdtemp(g_root)) {
+        fprintf(stderr, "host_control_link_harness: could not create a temp data root\n");
+        return 1;
+    }
+
+    test_fixtures();
+    test_parse_edges();
+    test_store();
+    test_loopback();
+
+    vd_remove_tree(g_root);
+    if (failures > 0) {
+        fprintf(stderr, "host_control_link_harness: %d failure(s)\n", failures);
+        return 1;
+    }
+    printf("host_control_link_harness: ok\n");
+    return 0;
+}
